import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
// Schema definition following strict rules


export type MegaphonePromoProps = Record<string, any>;

const MegaphonePromo: React.FC<MegaphonePromoProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 4,
  primaryBlue = "#0066FF",
  secondaryBlue = "#00AAFF",
  shadowColor = "rgba(0, 102, 255, 0.25)",
  pulseRateFrames = 75,
  waveCount = 3,
  particleCount = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Handle parser safety for transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Base visual scale to give presence within the 1000x1000 viewBox
  const baseVisualScale = 2.8;

  // --- Animation Dynamics ---

  // Snappy elastic bounce for the main megaphone pop-in
  const popSpring = spring({
    frame,
    fps,
    config: { damping: 9, stiffness: 220, mass: 0.8 },
  });

  const megaphoneScale = interpolate(popSpring, [0, 1], [0, 1]);
  // Slight swing rotation on entry for added organic feel
  const megaphoneRotate = interpolate(popSpring, [0, 1], [-25, 0]);

  // Delay the sound waves slightly so the megaphone has time to appear
  const wavesStartFrame = 12;
  const activeFrame = Math.max(0, frame - wavesStartFrame);

  // Initial burst progress for particles
  const burstSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120 },
    delay: 2,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg
        width="100%"
        height="100%"
        viewBox="-500 -500 1000 1000"
        style={{ overflow: "visible" }}
      >
        <defs>
          <linearGradient id="brandGradient" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor={primaryBlue} />
            <stop offset="100%" stopColor={secondaryBlue} />
          </linearGradient>

          <filter
            id="premiumShadow"
            x="-50%"
            y="-50%"
            width="200%"
            height="200%"
            colorInterpolationFilters="sRGB"
          >
            <feDropShadow
              dx="0"
              dy="15"
              stdDeviation="20"
              floodColor={shadowColor}
              floodOpacity="1"
            />
          </filter>
        </defs>

        {/* Master Group: Offset slightly left so the entire composition (megaphone + waves) feels centered */}
        <g transform={`translate(${-40 * baseVisualScale}, 0)`}>
          
          {/* Particles / Confetti Burst (Rendered behind the megaphone) */}
          <g transform={`scale(${baseVisualScale})`}>
            {Array.from({ length: particleCount }).map((_, i) => {
              const angle = (i / particleCount) * Math.PI * 2;
              const isCircle = i % 2 === 0;
              const maxDist = isCircle ? 120 : 160;

              const dist = interpolate(burstSpring, [0, 1], [20, maxDist]);
              const x = Math.cos(angle) * dist;
              const y = Math.sin(angle) * dist;

              const opacity = interpolate(burstSpring, [0, 0.6, 1], [1, 1, 0]);
              const scale = interpolate(burstSpring, [0, 0.2, 1], [0, 1, 0.5]);
              const rotation = frame * 3 + i * 45;

              return (
                <g
                  key={`particle-${i}`}
                  transform={`translate(${x}, ${y}) scale(${scale}) rotate(${rotation})`}
                  opacity={opacity}
                >
                  {isCircle ? (
                    <circle r="4" fill="url(#brandGradient)" />
                  ) : (
                    <rect
                      x="-3"
                      y="-8"
                      width="6"
                      height="16"
                      rx="3"
                      fill="url(#brandGradient)"
                    />
                  )}
                </g>
              );
            })}
          </g>

          {/* Megaphone and Waves */}
          <g
            transform={`scale(${megaphoneScale * baseVisualScale}) rotate(${megaphoneRotate})`}
          >
            {/* --- Sound Waves --- */}
            {Array.from({ length: waveCount }).map((_, i) => {
              const delay = i * (pulseRateFrames / waveCount);
              const localFrame = activeFrame - delay;

              // Don't render the wave until its specific start time
              if (localFrame < 0) return null;

              const progress = (localFrame % pulseRateFrames) / pulseRateFrames;

              // Wave expanding outward and fading
              const tx = interpolate(progress, [0, 1], [40, 180]);
              const waveScale = interpolate(progress, [0, 1], [0.4, 2.2]);
              const waveOpacity = interpolate(
                progress,
                [0, 0.1, 0.6, 1],
                [0, 1, 0.8, 0]
              );
              const strokeWidth = interpolate(progress, [0, 1], [12, 3]);

              return (
                <g
                  key={`wave-${i}`}
                  transform={`translate(${tx}, 0) scale(${waveScale})`}
                  opacity={waveOpacity}
                >
                  <path
                    d="M 10 -25 Q 40 0 10 25"
                    fill="none"
                    stroke="url(#brandGradient)"
                    strokeWidth={strokeWidth}
                    strokeLinecap="round"
                    vectorEffect="non-scaling-stroke"
                  />
                </g>
              );
            })}

            {/* --- Megaphone Icon --- */}
            <g filter="url(#premiumShadow)">
              {/* Handle */}
              <path
                d="M -15 20 L -15 60 A 8 8 0 0 0 -7 68 L 12 68 A 8 8 0 0 0 20 60 L 20 35"
                fill="none"
                stroke="url(#brandGradient)"
                strokeWidth="14"
                strokeLinecap="round"
                strokeLinejoin="round"
              />

              {/* Mouthpiece base (Back) */}
              <rect
                x="-70"
                y="-20"
                width="16"
                height="40"
                rx="6"
                fill="url(#brandGradient)"
              />

              {/* Main Cone */}
              <path
                d="M -60 -15 L 45 -55 Q 55 -55 55 -45 L 55 45 Q 55 55 45 55 L -60 15 Z"
                fill="url(#brandGradient)"
              />

              {/* Inner Structure / Highlights for premium feel */}
              {/* Top edge highlight */}
              <path
                d="M -55 -12 L 40 -50"
                stroke="#ffffff"
                strokeWidth="2.5"
                strokeLinecap="round"
                opacity="0.35"
                fill="none"
              />
              {/* Front edge rim depth */}
              <path
                d="M 45 -48 L 45 48"
                stroke="#ffffff"
                strokeWidth="3"
                strokeLinecap="round"
                opacity="0.4"
                fill="none"
              />
              {/* Bottom edge inner shadow representation */}
              <path
                d="M -55 12 L 40 50"
                stroke="#000000"
                strokeWidth="2.5"
                strokeLinecap="round"
                opacity="0.15"
                fill="none"
              />
            </g>
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default MegaphonePromo;